pub fn explicit_witness_admission_cadence_executes(cadence: WitnessConsumerCadence) -> bool {
    (crate::std_witness_admission::witness_cadence_has_scheduled_route(cadence.clone()) && match cadence.clone() {
    WitnessConsumerCadence::DiscoverySelection => false,
    WitnessConsumerCadence::OfflineLocalRecipe => false,
    WitnessConsumerCadence::FixtureExplicitRoster => false,
    WitnessConsumerCadence::NoConsumer => false,
    WitnessConsumerCadence::LocalRepoWetLane => true,
    WitnessConsumerCadence::FalsifierSelfHostWet => true,
    WitnessConsumerCadence::FalsifierRehomedBinWet => true,
    WitnessConsumerCadence::FalsifierSubstrateLongLane => true,
    WitnessConsumerCadence::BinWitnessWet => true,
    WitnessConsumerCadence::QuarantineProbeExpectRed => true,
})
}

pub fn is_transitional_admission_row(entry: String, function: String) -> bool {
    crate::std_algebra::non_empty_to_list(transitional_admission_exception_identities()).iter().cloned().fold(false, |found: bool, id: String| (found || (id.clone() == v1_rt::concat(v1_rt::concat(entry.clone(), "::".to_string()), function.clone()))))
}

pub fn explicit_witness_admission_well_formed(row: Rc<ExplicitWitnessAdmission>) -> bool {
    (!(row.witness.entry.clone() == "".to_string()) && (explicit_witness_admission_cadence_executes(row.cadence.clone()) || (is_transitional_admission_row(row.witness.entry.clone(), row.witness.function.clone()) && match row.cadence.clone() {
    WitnessConsumerCadence::QuarantineProbeExpectRed => true,
    WitnessConsumerCadence::FalsifierSubstrateLongLane => true,
    WitnessConsumerCadence::BinWitnessWet => true,
    WitnessConsumerCadence::DiscoverySelection => false,
    WitnessConsumerCadence::FalsifierSelfHostWet => false,
    WitnessConsumerCadence::FalsifierRehomedBinWet => false,
    WitnessConsumerCadence::LocalRepoWetLane => false,
    WitnessConsumerCadence::OfflineLocalRecipe => false,
    WitnessConsumerCadence::FixtureExplicitRoster => false,
    WitnessConsumerCadence::NoConsumer => false,
})))
}

pub fn explicit_witness_admissions_well_formed_in(rows: Rc<Vec<Rc<ExplicitWitnessAdmission>>>) -> bool {
    rows.iter().cloned().fold(true, |ok: bool, row: Rc<ExplicitWitnessAdmission>| (ok && explicit_witness_admission_well_formed(row.clone())))
}

pub fn explicit_witness_admissions_well_formed() -> bool {
    explicit_witness_admissions_well_formed_in(explicit_witness_admissions())
}
